#include <iostream>
#include <fstream>
#include <string>
#include <unordered_map>
#include <mutex>
#include <cstdlib>
#include <cstring>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <sstream>
#include <functional>
#include <chrono>
#include <thread>

namespace dcache {

struct FeatureFlags {
    bool enable_compression = false;
    bool enable_persistence = true;
    bool enable_atomic_writes = true;
    int max_retries = 3;
    std::string cache_dir = "/tmp";
    mode_t dir_permissions = 0700;
    mode_t file_permissions = 0600;
};

class TempFileManager {
private:
    FeatureFlags flags_;
    std::mutex mtx_;
    std::unordered_map<std::string, std::string> pending_writes_;

    std::string compute_cache_path(const std::string& key) {
        std::hash<std::string> hasher;
        size_t h = hasher(key);
        std::ostringstream oss;
        oss << flags_.cache_dir << "/dcache_" << std::hex << h;
        return oss.str();
    }

    std::string create_staging_path(const std::string& target_path) {
        // Create a staging file for atomic rename
        std::string staging = target_path + ".staging";
        return staging;
    }

    int open_staging_file(const std::string& path) {
        int fd;
        if (flags_.enable_atomic_writes) {
            // Use O_CREAT|O_EXCL for atomic creation
            fd = open(path.c_str(), O_WRONLY | O_CREAT | O_EXCL, flags_.file_permissions);
            if (fd < 0 && errno == EEXIST) {
                // Stale staging file exists, remove and retry
                unlink(path.c_str());
                fd = open(path.c_str(), O_WRONLY | O_CREAT | O_EXCL, flags_.file_permissions);
            }
        } else {
            fd = open(path.c_str(), O_WRONLY | O_CREAT | O_TRUNC, flags_.file_permissions);
        }
        return fd;
    }

    bool write_and_finalize(const std::string& staging_path,
                           const std::string& target_path,
                           const std::string& data) {
        int fd = open_staging_file(staging_path);
        if (fd < 0) return false;

        ssize_t written = write(fd, data.c_str(), data.size());
        if (written != static_cast<ssize_t>(data.size())) {
            close(fd);
            unlink(staging_path.c_str());
            return false;
        }
        fsync(fd);
        close(fd);

        if (flags_.enable_atomic_writes) {
            if (rename(staging_path.c_str(), target_path.c_str()) != 0) {
                unlink(staging_path.c_str());
                return false;
            }
        }
        return true;
    }

public:
    explicit TempFileManager(const FeatureFlags& flags) : flags_(flags) {
        mkdir(flags_.cache_dir.c_str(), flags_.dir_permissions);
    }

    bool persist_entry(const std::string& key, const std::string& value) {
        if (!flags_.enable_persistence) return true;

        std::lock_guard<std::mutex> lock(mtx_);
        std::string target = compute_cache_path(key);
        std::string staging = create_staging_path(target);

        for (int attempt = 0; attempt < flags_.max_retries; ++attempt) {
            if (write_and_finalize(staging, target, value)) {
                return true;
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
        return false;
    }

    std::string load_entry(const std::string& key) {
        std::string path = compute_cache_path(key);
        std::ifstream ifs(path);
        if (!ifs.is_open()) return "";
        std::ostringstream oss;
        oss << ifs.rdbuf();
        return oss.str();
    }
};

class DistributedCacheClient {
private:
    TempFileManager file_mgr_;
    std::unordered_map<std::string, std::string> memory_cache_;
    std::mutex cache_mtx_;
    FeatureFlags flags_;

public:
    explicit DistributedCacheClient(const FeatureFlags& flags)
        : file_mgr_(flags), flags_(flags) {}

    void put(const std::string& key, const std::string& value) {
        {
            std::lock_guard<std::mutex> lock(cache_mtx_);
            memory_cache_[key] = value;
        }
        file_mgr_.persist_entry(key, value);
    }

    std::string get(const std::string& key) {
        {
            std::lock_guard<std::mutex> lock(cache_mtx_);
            auto it = memory_cache_.find(key);
            if (it != memory_cache_.end()) return it->second;
        }
        std::string val = file_mgr_.load_entry(key);
        if (!val.empty()) {
            std::lock_guard<std::mutex> lock(cache_mtx_);
            memory_cache_[key] = val;
        }
        return val;
    }
};

} // namespace dcache

int main() {
    dcache::FeatureFlags flags;
    flags.enable_persistence = true;
    flags.enable_atomic_writes = true;
    flags.cache_dir = "/tmp/dcache_test";

    dcache::DistributedCacheClient client(flags);
    client.put("session:abc123", "user_token=secret_value_42");
    std::string val = client.get("session:abc123");
    std::cout << "Retrieved: " << val << std::endl;
    return 0;
}
